#!/usr/bin/env node
// Writes apps/web/src/canvas/previewModules.generated.ts: the three.js ES-module files AwwO's previews supply to a
// delivered page (the core build and a curated set of addons), each with its size, sha256 and the files it imports.
// The bytes come from the npm release installed in apps/web/node_modules/three, which must be exactly VERSION.
//
//   node scripts/preview-modules.mjs          (rewrite the generated file)
//   node scripts/preview-modules.mjs --check  (exit 1 when the generated file is out of date)
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const THREE = path.join(ROOT, 'apps/web/node_modules/three');
const OUT = path.join(ROOT, 'apps/web/src/canvas/previewModules.generated.ts');
const VERSION = '0.186.1';

// Entry points a page may import (their own imports come along). Left out on purpose: loaders and physics that fetch
// a decoder or WebAssembly from a CDN path at run time (DRACO, KTX2, Rapier, Basis), and the WebGPU/TSL builds.
const ENTRIES = [
  'build/three.module.js',
  ...['OrbitControls', 'MapControls', 'PointerLockControls', 'TransformControls', 'FirstPersonControls'].map(name => `examples/jsm/controls/${name}.js`),
  ...['GLTFLoader', 'HDRLoader', 'RGBELoader', 'FontLoader', 'SVGLoader', 'OBJLoader'].map(name => `examples/jsm/loaders/${name}.js`),
  'examples/jsm/environments/RoomEnvironment.js',
  ...['Sky', 'Water', 'Reflector', 'Lensflare'].map(name => `examples/jsm/objects/${name}.js`),
  ...['EffectComposer', 'RenderPass', 'ShaderPass', 'OutputPass', 'UnrealBloomPass', 'BloomPass', 'SMAAPass', 'FXAAPass', 'GTAOPass', 'SSAOPass',
    'SAOPass', 'BokehPass', 'FilmPass', 'AfterimagePass', 'GlitchPass', 'OutlinePass', 'RenderPixelatedPass', 'HalftonePass', 'DotScreenPass',
    'LUTPass', 'TAARenderPass', 'TexturePass', 'ClearPass', 'MaskPass'].map(name => `examples/jsm/postprocessing/${name}.js`),
  ...['FXAAShader', 'VignetteShader', 'RGBShiftShader', 'GammaCorrectionShader', 'ColorCorrectionShader', 'HueSaturationShader',
    'BrightnessContrastShader', 'CopyShader'].map(name => `examples/jsm/shaders/${name}.js`),
  ...['CSS2DRenderer', 'CSS3DRenderer'].map(name => `examples/jsm/renderers/${name}.js`),
  ...['RoundedBoxGeometry', 'TextGeometry', 'ConvexGeometry'].map(name => `examples/jsm/geometries/${name}.js`),
  ...['Line2', 'LineMaterial', 'LineGeometry', 'LineSegments2', 'LineSegmentsGeometry'].map(name => `examples/jsm/lines/${name}.js`),
  ...['SimplexNoise', 'ImprovedNoise'].map(name => `examples/jsm/math/${name}.js`),
  'examples/jsm/misc/GPUComputationRenderer.js',
  ...['BufferGeometryUtils', 'SkeletonUtils', 'GeometryUtils'].map(name => `examples/jsm/utils/${name}.js`),
  'examples/jsm/effects/OutlineEffect.js',
  'examples/jsm/animation/AnimationClipCreator.js',
  'examples/jsm/modifiers/CurveModifier.js',
  'examples/jsm/textures/FlakesTexture.js',
  'examples/jsm/libs/stats.module.js',
];

/** The static import/export specifiers of a module, as written. Only statements that start a line count, so the
 * `@three_import import { … } from 'three/addons/…'` lines of three's doc comments never do. */
export function moduleSpecifiers(text) {
  const found = [];
  for (const match of text.matchAll(/^[ \t]*(?:import|export)\b(?:[^'";]|\n)*?\bfrom\s*(['"])([^'"\n]+)\1|^[ \t]*import\s*(['"])([^'"\n]+)\3/gm)) {
    found.push(match[2] ?? match[4]);
  }
  return found;
}

const version = JSON.parse(readFileSync(path.join(THREE, 'package.json'), 'utf8')).version;

function main() {
if (version !== VERSION) throw new Error(`apps/web/node_modules/three is ${version}, expected ${VERSION}`);

const files = new Map();
function visit(file) {
  if (files.has(file)) return;
  const bytes = readFileSync(path.join(THREE, file));
  const text = bytes.toString('utf8');
  const imports = [];
  let bare = false;
  for (const specifier of moduleSpecifiers(text)) {
    if (specifier === 'three') { bare = true; continue; }
    if (!specifier.startsWith('./') && !specifier.startsWith('../')) throw new Error(`${file}: unexpected import ${specifier}`);
    const target = path.posix.normalize(path.posix.join(path.posix.dirname(file), specifier));
    if (!imports.some(entry => entry.specifier === specifier)) imports.push({ specifier, file: target });
  }
  files.set(file, { bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex'), bare, imports });
  for (const entry of imports) visit(entry.file);
}
for (const entry of ENTRIES) visit(entry);

const sorted = [...files.entries()].sort(([a], [b]) => a.localeCompare(b));
const fromSource = path.posix.relative('apps/web/src/canvas', 'apps/web/node_modules/three');
const lines = [
  '// Generated by scripts/preview-modules.mjs from the npm release three@' + VERSION + '; do not edit by hand.',
  '// Each file: its size (checked when it loads) and sha256 (checked by tests), whether it imports the bare specifier',
  "// 'three', and the relative imports it makes (as written, and the file each one names).",
  '',
  `export const THREE_MODULES_VERSION = '${VERSION}';`,
  '',
  'export interface GeneratedModuleFile {',
  '  readonly bytes: number;',
  '  readonly sha256: string;',
  '  readonly bare: boolean;',
  '  readonly imports: ReadonlyArray<{ readonly specifier: string; readonly file: string }>;',
  '  readonly load: () => Promise<string>;',
  '}',
  '',
  'export const THREE_MODULE_FILES: Readonly<Record<string, GeneratedModuleFile>> = {',
  ...sorted.map(([file, entry]) => `  ${JSON.stringify(file)}: { bytes: ${entry.bytes}, sha256: '${entry.sha256}', bare: ${entry.bare}, imports: ${JSON.stringify(entry.imports)},\n`
    + `    load: () => import('${fromSource}/${file}?raw').then(module => module.default) },`),
  '};',
  '',
];
const output = lines.join('\n');
if (process.argv.includes('--check')) {
  let current = '';
  try { current = readFileSync(OUT, 'utf8'); } catch { /* missing */ }
  if (current !== output) { console.error(`${path.relative(ROOT, OUT)} is out of date: run node scripts/preview-modules.mjs`); process.exit(1); }
  console.log(`${path.relative(ROOT, OUT)} is up to date (${files.size} files)`);
} else {
  writeFileSync(OUT, output);
  const total = sorted.reduce((sum, [, entry]) => sum + entry.bytes, 0);
  console.log(`wrote ${path.relative(ROOT, OUT)}: ${files.size} files, ${(total / 1024).toFixed(0)} KiB`);
}
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
